// Regression test for issue #349.
//
// `zfa entity create --allow-forward-refs --field url:WebUri?` emitted:
//   1. A `$`-prefixed type `$WebUri` — wrong for external (non-entity) types
//      that are never generated by zorphy.
//   2. A bogus import `import '../web_uri/web_uri.dart';` for a directory
//      that does not exist, or `import '../enums/index.dart';` for a type
//      that is not an enum.
//
// Root cause: `FieldNormalizer._determinePrefix()` returned `$` for any
// type without an on-disk entity file, assuming it was a forward-ref entity.
// `ImportResolver` assumed any non-primitive, non-entity type was an enum
// and added `enums/index.dart`. There was no way to declare a type as
// external (never an entity, never an enum).
//
// Fix (this PR): the `!Type` prefix syntax marks a field type as external.
// `--field url:!WebUri?` keeps `WebUri?` as-is (no `$` prefix, no validation,
// no import emission). This works both with and without `--allow-forward-refs`.
//
// This test locks in the fix end-to-end by spawning the `zfa` CLI binary
// against a temp workspace.

import 'dart:io';

import 'package:path/path.dart' as p;
import 'package:test/test.dart';

/// Resolve package root at discovery time, before any test changes CWD.
final _zfaRoot = Directory.current.path;

void main() {
  group('#349 — !Type prefix for external (non-entity) types', () {
    late Directory workspace;
    late String zfaBin;

    Future<ProcessResult> runZfa(List<String> args) {
      return Process.run(
        'dart',
        [zfaBin, ...args],
        workingDirectory: workspace.path,
      );
  }

    setUp(() async {
      zfaBin = p.join(_zfaRoot, 'bin', 'zfa.dart');
      workspace = await Directory.systemTemp.createTemp('issue_349_');
      await File(p.join(workspace.path, 'pubspec.yaml')).writeAsString('''
name: issue_349_test_app
environment:
  sdk: '>=3.12.0 <4.0.0'
dependencies:
  zorphy_annotation:
dev_dependencies:
  build_runner:
''');
    });

    tearDown(() async {
      if (workspace.existsSync()) {
        await workspace.delete(recursive: true);
      }
    });

    test(
      'external type WITH ! prefix keeps type as-is, no bogus import',
      timeout: const Timeout(Duration(minutes: 2)),
      () async {
        final result = await runZfa([
          'entity',
          'create',
          '-n',
          'JsAlertRequest',
          '--kind=value_object',
          '--field',
          'url:!WebUri?',
          '--field',
          'message:String?',
          '--allow-forward-refs',
        ]);

        expect(
          result.exitCode,
          equals(0),
          reason: '! prefix must be accepted with --allow-forward-refs',
        );

        final entityFile = File(
          p.join(
            workspace.path,
            'lib',
            'src',
            'domain',
            'entities',
            'js_alert_request',
            'js_alert_request.dart',
          ),
        );
        expect(entityFile.existsSync(), isTrue);

        final content = await entityFile.readAsString();

        // The type must be `WebUri?`, NOT `$WebUri?`.
        expect(
          content,
          contains('WebUri? get url'),
          reason:
              '! prefix must keep the type name as-is without \$ prefix',
        );
        expect(
          content,
          isNot(contains('\$WebUri')),
          reason: 'External type must NOT be \$-prefixed',
        );

        // No bogus entity import for the external type.
        expect(
          content,
          isNot(contains("import '../web_uri/web_uri.dart';")),
          reason: 'No entity-style import for external types',
        );

        // No bogus enum import either.
        expect(
          content,
          isNot(contains("import '../enums/index.dart';")),
          reason: 'No enum import for external types',
        );
      },
    );

    test(
      'external type WITH ! prefix but WITHOUT --allow-forward-refs is accepted',
      timeout: const Timeout(Duration(minutes: 2)),
      () async {
        final result = await runZfa([
          'entity',
          'create',
          '-n',
          'JsAlertRequest',
          '--kind=value_object',
          '--field',
          'url:!WebUri?',
          '--field',
          'message:String?',
        ]);

        expect(
          result.exitCode,
          equals(0),
          reason:
              '! prefix must bypass on-disk validation even without --allow-forward-refs',
        );

        final entityFile = File(
          p.join(
            workspace.path,
            'lib',
            'src',
            'domain',
            'entities',
            'js_alert_request',
            'js_alert_request.dart',
          ),
        );
        expect(entityFile.existsSync(), isTrue);

        final content = await entityFile.readAsString();

        expect(content, contains('WebUri? get url'));
        expect(content, isNot(contains('\$WebUri')));
        expect(content, isNot(contains("import '../web_uri/web_uri.dart';")));
        expect(content, isNot(contains("import '../enums/index.dart';")));
      },
    );

    test(
      'add-field with ! prefix adds external type without \$ prefix',
      timeout: const Timeout(Duration(minutes: 2)),
      () async {
        final create = await runZfa([
          'entity',
          'create',
          '-n',
          'JsAlertRequest',
          '--kind=value_object',
          '--field',
          'message:String?',
        ]);
        expect(create.exitCode, equals(0));

        final add = await runZfa([
          'entity',
          'add-field',
          '-n',
          'JsAlertRequest',
          '--field',
          'url:!WebUri?',
        ]);
        expect(
          add.exitCode,
          equals(0),
          reason: '! prefix must be accepted for add-field',
        );

        final entityFile = File(
          p.join(
            workspace.path,
            'lib',
            'src',
            'domain',
            'entities',
            'js_alert_request',
            'js_alert_request.dart',
          ),
        );
        expect(entityFile.existsSync(), isTrue);

        final content = await entityFile.readAsString();

        expect(
          content,
          contains('WebUri? get url'),
          reason: 'External type must not be \$-prefixed in add-field',
        );
        expect(content, isNot(contains('\$WebUri')));
      },
    );

    test(
      'zfa binary is runnable (smoke)',
      timeout: const Timeout(Duration(minutes: 2)),
      () async {
        final result = await Process.run(
          'dart',
          [zfaBin, '--help'],
          workingDirectory: _zfaRoot,
        );
        expect(result.exitCode, equals(0));
      },
    );
  });
}
